function decryptStoredToken(value){const secret=process.env.BOT_TOKEN_ENCRYPTION_KEY;if(!secret)throw Error('BOT_TOKEN_ENCRYPTION_KEY missing');const [iv,tag,data]=String(value||'').split(':');if(!iv||!tag||!data)throw Error('invalid encrypted token');const key=crypto.createHash('sha256').update(secret).digest(),decipher=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(iv,'base64'));decipher.setAuthTag(Buffer.from(tag,'base64'));return Buffer.concat([decipher.update(Buffer.from(data,'base64')),decipher.final()]).toString('utf8')}
